"""shop.py: the simulated shop for Lab 4 (you do not edit this file).

A tiny shop with a database that is just a dict, three tools and a step counter:

    lookup_order(order)             read-only: the order's record, or "error: no such order"
    refund_item(order, item)        remove the item from a delivered order, record the refund, restock it
    change_address(order, address)  change the address of an order that has not shipped yet

The tools check what the database can check (status, whether the item is in the order). They do NOT
check the shop's return window (30 days): that is policy, and policy lives in the agent. A tool that
let an agent do anything the database allows is how real agents refund things they should not.

Shop wraps one database for one trial. Every tool call is a "step": it is logged in the transcript and
charged as one model turn, whose input grows as the conversation grows. A call past max_steps raises
StepCapExceeded, the harness's guard against a runaway loop.
"""
import copy

RETURN_WINDOW_DAYS = 30

# The starting snapshot. Every trial starts from a fresh deep copy of it.
START = {
    "orders": {
        "A100": {"status": "delivered",  "days_since_delivery": 4,    "items": ["kettle"],         "refund": 0, "address": "12 Mill Lane"},
        "A101": {"status": "delivered",  "days_since_delivery": 6,    "items": ["lamp", "mug"],    "refund": 0, "address": "3 Orchard Close"},
        "A102": {"status": "shipped",    "days_since_delivery": None, "items": ["desk"],           "refund": 0, "address": "88 High Street"},
        "A103": {"status": "processing", "days_since_delivery": None, "items": ["rug", "mug"],     "refund": 0, "address": "7 Quarry Road"},
        "A104": {"status": "delivered",  "days_since_delivery": 45,   "items": ["mug"],            "refund": 0, "address": "21 Canal Walk"},
        "A105": {"status": "delivered",  "days_since_delivery": 10,   "items": ["lamp", "kettle"], "refund": 0, "address": "9 Beech Avenue"},
        "A106": {"status": "processing", "days_since_delivery": None, "items": ["kettle"],         "refund": 0, "address": "40 Station Road"},
        "A107": {"status": "delivered",  "days_since_delivery": 12,   "items": ["rug"],            "refund": 0, "address": "5 Rowan Way"},
    },
    "stock": {"kettle": 5, "lamp": 2, "mug": 9, "desk": 1, "rug": 3},
}
PRICES = {"kettle": 30, "lamp": 25, "mug": 8, "desk": 140, "rug": 60}

# Token accounting for the cost figures: a model turn reads the whole conversation so far.
BASE_CONTEXT, PER_TURN_CONTEXT = 600, 350
TOOL_TURN_OUT, REPLY_TURN_OUT = 70, 90


class StepCapExceeded(Exception):
    """The agent tried to make more tool calls than the harness allows."""


def lookup_order(db, order):
    if order not in db["orders"]:
        return "error: no such order"
    return copy.deepcopy(db["orders"][order])


def refund_item(db, order, item):
    o = db["orders"].get(order)
    if o is None:
        return "error: no such order"
    if o["status"] != "delivered" or item not in o["items"]:
        return "error: not eligible"
    o["items"].remove(item)
    o["refund"] += PRICES[item]
    db["stock"][item] += 1
    return f"ok: refunded {PRICES[item]}"


def change_address(db, order, address):
    o = db["orders"].get(order)
    if o is None:
        return "error: no such order"
    if o["status"] != "processing":
        return "error: order already shipped"
    o["address"] = address
    return "ok"


TOOLS = {"lookup_order": lookup_order, "refund_item": refund_item, "change_address": change_address}


class Shop:
    """One trial's world: the database, the tools, a transcript and the token meter."""

    def __init__(self, db, max_steps=12):
        self.db = db
        self.max_steps = max_steps
        self.transcript = []          # one {"tool", "args", "result"} per tool call
        self.turns = 0
        self.tokens_in = 0
        self.tokens_out = 0
        self.reply = None

    def _turn(self, out_tokens):
        self.tokens_in += BASE_CONTEXT + PER_TURN_CONTEXT * self.turns
        self.tokens_out += out_tokens
        self.turns += 1

    def call(self, tool, **args):
        """Call a tool. Raises StepCapExceeded if max_steps calls have already been made."""
        if len(self.transcript) >= self.max_steps:
            raise StepCapExceeded(f"more than {self.max_steps} tool calls")
        self._turn(TOOL_TURN_OUT)
        result = TOOLS[tool](self.db, **args)
        self.transcript.append({"tool": tool, "args": args, "result": result})
        return result

    def say(self, text):
        """The agent's final message to the customer (one more model turn). Returns the text."""
        self._turn(REPLY_TURN_OUT)
        self.reply = text
        return text
